// Test-only DDS boundary: asserts resource, epoch and exception safety.
// No genuine DDS traffic is generated by this test.
#include "umaa/cyclone_command_reader.hpp"
#include <cassert>
#include <cstdlib>
#include <stdexcept>

struct dds_qos {};
struct dds_topic_descriptor {};
struct Wire { int* value; };
static int create_calls, take_calls, delete_calls, free_calls;
static bool create_error, take_error, delete_error;
static int queue_kind; // 0: empty, 1: data, 2: dispose
extern "C" dds_entity_t dds_create_reader(dds_entity_t p, dds_entity_t t,
                                             const dds_qos_t* q, const void*) {
  assert(p == 1 && t == 2 && q != nullptr);
  ++create_calls;
  return create_error ? -1 : 10 + create_calls;
}
extern "C" dds_return_t dds_take(dds_entity_t reader, void** samples,
                                   dds_sample_info_t* info, size_t bufsz, uint32_t maxs) {
  assert(reader > 10 && bufsz == 1 && maxs == 1);
  ++take_calls;
  if (take_error) return -2;
  if (queue_kind == 0) return 0;
  auto* data = static_cast<Wire*>(samples[0]);
  data->value = static_cast<int*>(std::malloc(sizeof(int)));
  assert(data->value);
  *data->value = 77;
  info[0].valid_data = queue_kind == 1;
  info[0].instance_state = queue_kind == 2 ? DDS_IST_NOT_ALIVE_DISPOSED : 0;
  queue_kind = 0;
  return 1;
}
extern "C" dds_return_t dds_delete(dds_entity_t reader) {
  assert(reader > 10);
  ++delete_calls;
  return delete_error ? -3 : 0;
}
extern "C" void dds_sample_free(void* sample, const dds_topic_descriptor_t*, uint32_t op) {
  assert(op == DDS_FREE_CONTENTS);
  auto* wire = static_cast<Wire*>(sample);
  std::free(wire->value);
  wire->value = nullptr;
  ++free_calls;
}
extern "C" const char* dds_strretcode(int32_t) { return "fake DDS error"; }

template<class F> void throws(F f) {
  bool caught = false;
  try { f(); } catch (const std::exception&) { caught = true; }
  assert(caught);
}
int main() {
  using Reader = umaa::cyclone::CommandReader<Wire>;
  dds_qos qos;
  dds_topic_descriptor desc;
  throws([&] { Reader r(0,2,&desc,&qos); });
  throws([&] { Reader r(1,0,&desc,&qos); });
  throws([&] { Reader r(1,2,nullptr,&qos); });
  throws([&] { Reader r(1,2,&desc,nullptr); });
  {
    Reader reader(1,2,&desc,&qos);
    throws([&] { reader.start(0); });
    create_error = true;
    throws([&] { reader.start(1); });
    assert(reader.entity() == 0 && !reader.faulted());
    create_error = false;
    reader.start(1);
    assert(reader.active_epoch() == 1 && reader.entity() > 0);
    throws([&] { reader.start(2); });
    throws([&] { reader.stop(2); });
    const int previous_takes = take_calls;
    throws([&] { reader.poll(2, [](const Wire&, const dds_sample_info_t&){}); });
    assert(take_calls == previous_takes); // mismatched epoch never consumes
    assert(!reader.poll(1, [](const Wire&, const dds_sample_info_t&){}));
    queue_kind = 1;
    bool got_data = false;
    assert(reader.poll(1, [&](const Wire& w, const dds_sample_info_t& info){
      assert(info.valid_data && *w.value == 77); got_data = true;
    }));
    assert(got_data && free_calls == 1);
    queue_kind = 2;
    assert(reader.poll(1, [&](const Wire& w, const dds_sample_info_t& info){
      assert(!info.valid_data && info.instance_state == DDS_IST_NOT_ALIVE_DISPOSED);
      assert(*w.value == 77);
    }));
    assert(free_calls == 2);
    reader.stop(1);
    assert(reader.entity() == 0 && reader.active_epoch() == 0);
    reader.start(3);
    throws([&] { reader.poll(1, [](const Wire&, const dds_sample_info_t&){}); });
    queue_kind = 1;
    throws([&] { reader.poll(3, [](const Wire&, const dds_sample_info_t&){
      throw std::runtime_error("user callback failure");
    }); });
    assert(free_calls == 3 && reader.faulted()); // sample freed, epoch fenced
    throws([&] { reader.poll(3, [](const Wire&, const dds_sample_info_t&){}); });
    throws([&] { reader.stop(3); });
  }
  assert(create_calls == 3 && delete_calls == 2);
  {
    Reader reader(1,2,&desc,&qos);
    reader.start(4);
    take_error = true;
    throws([&] { reader.poll(4, [](const Wire&, const dds_sample_info_t&){}); });
    assert(reader.faulted());
    take_error = false;
    throws([&] { reader.poll(4, [](const Wire&, const dds_sample_info_t&){}); });
    // Destructor releases reader after fault, never throws.
  }
  assert(delete_calls == 3);
  {
    Reader reader(1,2,&desc,&qos);
    reader.start(5);
    delete_error = true;
    throws([&] { reader.stop(5); });
    assert(reader.faulted() && reader.entity() > 0);
    throws([&] { reader.start(6); });
    delete_error = false;
  }
  assert(delete_calls == 5);
}
